def build_linked_list(values: List[int], pos: int) -> Optional[ListNode]:
    if not values:
        return None

    nodes = [ListNode(val) for val in values]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]

    if pos != -1 and pos < len(nodes):
        nodes[-1].next = nodes[pos]

    return nodes[0]

